import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css";

function IncomeCategory({ onNext }) {
  const [selected, setSelected] = useState("");
  const navigate = useNavigate();

  const handleContinue = () => {
    if (!selected) {
      alert("Please select an income type");
      return;
    }

    onNext(selected);
    navigate("/questionnaire");
  };

  return (
    <div className="income-container">
      <h2>Select Your Income Type</h2>

      <div className="income-options">
        <button onClick={() => setSelected("Salary")}>Salary</button>
        <button onClick={() => setSelected("Business")}>Business</button>
        <button onClick={() => setSelected("Student")}>Student</button>
        <button onClick={() => setSelected("No Income")}>No Income</button>
      </div>

      <button className="continue-btn" onClick={handleContinue}>
        Continue
      </button>
    </div>
  );
}

export default IncomeCategory;
